changeSet.sql:
INSERT INTO permissions (permission_id, name, api_path, http_method, module, created_at, updated_at, created_by, updated_by, version) SELECT UUID(), 'Workspace delete', '/api/v1/workspaces/{workspaceId}', 'DELETE', 'COLLAB', NOW(6), NOW(6), 'system', 'system', 0 WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE api_path = '/api/v1/workspaces/{workspaceId}' AND http_method = 'DELETE');
INSERT INTO permissions (permission_id, name, api_path, http_method, module, created_at, updated_at, created_by, updated_by, version) SELECT UUID(), 'Project delete', '/api/v1/projects/{projectId}', 'DELETE', 'COLLAB', NOW(6), NOW(6), 'system', 'system', 0 WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE api_path = '/api/v1/projects/{projectId}' AND http_method = 'DELETE');
INSERT INTO permission_roles (role_id, permission_id) SELECT r.role_id, p.permission_id FROM roles r JOIN permissions p ON p.api_path = '/api/v1/workspaces/{workspaceId}' AND p.http_method = 'DELETE' WHERE r.name IN ('ADMIN', 'USER') AND NOT EXISTS ( SELECT 1 FROM permission_roles pr WHERE pr.role_id = r.role_id AND pr.permission_id = p.permission_id );
INSERT INTO permission_roles (role_id, permission_id) SELECT r.role_id, p.permission_id FROM roles r JOIN permissions p ON p.api_path = '/api/v1/projects/{projectId}' AND p.http_method = 'DELETE' WHERE r.name IN ('ADMIN', 'USER') AND NOT EXISTS ( SELECT 1 FROM permission_roles pr WHERE pr.role_id = r.role_id AND pr.permission_id = p.permission_id );
